#include <stdio.h>
int main() {
    int x = 8;
    switch(x) {
        case 0:
        case 1:
            printf("zero or one\n");
            break;
        case 2:
            printf("two\n");
            /* fall through */
        case 3:
            printf("three\n");
            break;
        case 4:
        case 5:
        case 6:
            printf("four to six\n");
            break;
        default:
            printf("default\n");
            break;
    }
    return 0;
}
